		for rows.Next() {
			var id string
			var from *string
			if err = rows.Scan(&id, &from); err != nil {
				rows.Close()
				return protocol.AssignResult{}, false, err
			}
			previous[id] = from
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return protocol.AssignResult{}, false, err
		}
		// Ineligible targets (missing, other tenant, own purchase or not submitted) all get the same 409.
		if len(previous) != len(ids) {
			return protocol.AssignResult{}, false, &protocol.Rejection{Status: 409}
		}
		tag, err := tx.Exec(ctx, `UPDATE "Purchase" SET "assigneeId"=$4 WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'`,
			ids, u.Tenant, u.User, assignee)
		if err != nil {
			return protocol.AssignResult{}, false, err
		}
		if tag.RowsAffected() != int64(len(ids)) {
			return protocol.AssignResult{}, false, &protocol.Rejection{Status: 409}
		}
		batch := &pgx.Batch{}
		for _, id := range ids {
			batch.Queue(`INSERT INTO "AssignmentHistory" ("tenantId","purchaseId","fromAssignee","toAssignee","changedBy",operation,"idempotencyKey") VALUES ($1,$2,$3,$4,$5,$6,$7)`,
				u.Tenant, id, previous[id], assignee, u.User, opReassign, key)
			batch.Queue(`INSERT INTO "PurchaseEvent" ("tenantId","purchaseId",type,"actorId","idempotencyKey") VALUES ($1,$2,'purchase.reassigned',$3,$4)`,
				u.Tenant, id, u.User, key)
		}
		result := protocol.AssignResult{Field: "reassignedIds", IDs: ids, Assignee: assignee}
		response, err := json.Marshal(result)
		if err != nil {
